function fakeBrowserify() {
    var b = new EventEmitter();
    b._pending = 0;
    b.ignored = [];
    b.excluded = [];
    b.externals = [];
    b.ignore = function (file) {
        b.ignored.push(file);
    };
    b.exclude = function (file) {
        b.excluded.push(file);
    };
    b.external = function (file, opts) {
        b.externals.push({ file: file, opts: opts || {} });
    };
    return b;
}

function ready(browserify) {
    return new Promise(function (resolve, reject) {
        browserify.once('_ready', resolve);
        browserify.once('error', reject);
    });
}

var sut = fakeBrowserify();
applyExtraOptions(sut, {
    ignore: [path.join(fixture, '*.js'), path.join(fixture, 'none-*')],
