            new Error(
                `EACCES: permission denied, watch '${tmpRoot}/src/app.js'`
            ),
            { code: 'EACCES', path: path.join(tmpRoot, 'src', 'app.js') }
        );

        t.doesNotThrow(
            () => watcher.watcher.emit('error', eacces),
            'a permission failure on a watched file is not fatal'
