            () => watcher.watcher.emit('error', enospc),
            'exhausting the watch limit is not fatal either'
        );

        t.ok(
            discovered.has('./src/app.js'),
            'the watcher keeps reporting the files it can read'
        );

        watcher.onExit();
        fs.rmSync(tmpRoot, { recursive: true, force: true });
    }
);

