class Boom {
    perform() {
        setTimeout(() => Promise.reject(new Error('outlet boom')), 0);
        return new Promise(() => {});
    }
}
module.exports = Boom;

const tap = require('tap');
const net = require('net');
const os = require('os');
const path = require('path');
const fs = require('fs');
const CacheClient = require('../src/cache/client');

const CONTENT_DELIMITER = '\u0004';

function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
}

async function waitFor(predicate, timeout = 10000) {
    const deadline = Date.now() + timeout;
    while (Date.now() < deadline) {
        if (predicate()) return true;
        await sleep(50);
    }
    return false;
}

tap.test('an errored entry is recorded and reported on the client', async (t) => {
    const socketPath = path.join(
        os.tmpdir(),
        `mendel-cc-${process.pid}-${Date.now()}.sock`
    );
    const server = net.createServer();
    await new Promise((resolve) => server.listen(socketPath, resolve));

    let connection;
    server.once('connection', (conn) => (connection = conn));

    const removed = [];
    const registry = {
        removeEntry: (id) => removed.push(id),
        clear: () => {},
    };

    const errors = [];
    const original = console.error;
    console.error = (...args) => errors.push(args.join(' '));

    t.teardown(() => {
        console.error = original;
    });

    const client = new CacheClient(
        {
            cacheConnection: { type: 'unix', path: socketPath },
            environment: 'development',
        },
        registry
    );

    t.teardown(() => {
        client.onExit();
        server.close();
        try {
            fs.unlinkSync(socketPath);
        } catch (e) {
            /* already gone */
        }
    });

    t.ok(
        await waitFor(() => connection),
        'the client connects to the live socket'
    );

    connection.write(
        JSON.stringify({
            type: 'errorEntry',
            id: 'app/main.js',
            totalEntries: 0,
            error: { message: 'boom', stack: 'Error: boom\n    at x' },
        }) + CONTENT_DELIMITER
    );

    t.ok(
        await waitFor(() => client.erroredEntries.size === 1),
        'the errored entry is tracked'
    );

    const [entryError] = client.getErrors();
    t.equal(entryError.id, 'app/main.js');
    t.equal(entryError.environment, 'development');
    t.equal(entryError.message, 'boom');
    t.deepEqual(
        removed,
        ['app/main.js'],
        'the errored entry is dropped from the registry'
    );

    t.ok(
        await waitFor(() =>
            errors.some(
                (line) =>
                    line.includes('[Mendel] Errored while parsing app/main.js') &&
                    line.includes('Error: boom')
            )
        ),
        'the parse error is reported with its stack'
    );
});

const tap = require('tap');
const net = require('net');
const os = require('os');
const path = require('path');
const fs = require('fs');
const UnixSocketNetwork = require('../src/cache/network/unix-socket');

tap.test('a live foreign server fails the precondition and is named', async (t) => {
    const socketPath = path.join(
        os.tmpdir(),
        `mendel-usk-${process.pid}-${Date.now()}.sock`
    );
    const server = net.createServer();
    await new Promise((resolve) => server.listen(socketPath, resolve));

    const errors = [];
    const original = console.error;
    console.error = (...args) => errors.push(args.join(' '));

    t.teardown(() => {
        console.error = original;
        server.close();
        try {
            fs.unlinkSync(socketPath);
        } catch (e) {
            /* already gone */
        }
    });

    await t.rejects(
        UnixSocketNetwork._serverPrecondition(socketPath),
        /Other Daemon Active/,
        'a live foreign server fails the precondition'
    );

    const reported = errors.join('\n');
    t.match(
        reported,
        /Another builder is already running/,
        'the report says a builder is already running'
    );
    t.match(
        reported,
        new RegExp(path.resolve(socketPath)),
        'the report names the socket to remove'
    );
});

const tap = require('tap');
const { EventEmitter } = require('events');
const os = require('os');
const path = require('path');
const MendelPipeline = require('../src/pipeline');

tap.test('a step error is reported and recorded on the cache', (t) => {
    const fakeCache = new EventEmitter();
    const entryErrors = [];
    fakeCache.setEntryError = (id, error) => entryErrors.push({ id, error });

    const options = {
        environment: 'development',
        types: [],
        transforms: [],
        baseConfig: { id: 'base' },
        variationConfig: { variations: {} },
        projectRoot: path.join(os.tmpdir(), 'mendel-pipeline-handle-error'),
    };

    const pipeline = new MendelPipeline({
        options,
        cache: fakeCache,
        transformer: {},
        depsResolver: {},
    });

    const errors = [];
    const original = console.error;
    console.error = (...args) => errors.push(args.join(' '));

    t.teardown(() => {
        console.error = original;
    });

    const error = new Error('ist exploded');
    pipeline.steps[0].emit('error', { error, id: 'app/main.js' });

    t.equal(errors.length, 3, 'the failure is reported in three lines');
    t.match(errors[0], /builder "Initialize" errored:/, 'names the step');
    t.match(errors[1], /ist exploded/, 'carries the error message');
    t.match(errors[2], /ist exploded/, 'carries the stack');

    t.equal(entryErrors.length, 1, 'the cache is told about the error');
    t.equal(entryErrors[0].id, 'app/main.js');
    t.equal(entryErrors[0].error, error);

    t.end();
});

const tap = require('tap');
const Mendel = require('../src/main');

tap.test('a recycled builder warns instead of failing', async (t) => {
    const daemonDescriptor = Object.getOwnPropertyDescriptor(Mendel, 'Daemon');
    const clientDescriptor = Object.getOwnPropertyDescriptor(Mendel, 'Client');

    class FakeDaemon {
        run(callback) {
            callback(new ReferenceError('Other Daemon Active'));
        }
        onForceExit() {}
    }

    class FakeClient {
        run(callback) {
            callback(null);
        }
    }

    Object.defineProperty(Mendel, 'Daemon', {
        value: FakeDaemon,
        configurable: true,
    });
    Object.defineProperty(Mendel, 'Client', {
        value: FakeClient,
        configurable: true,
    });

    const warnings = [];
    const originalWarn = console.warn;
    console.warn = (...args) => warnings.push(args.join(' '));

    t.teardown(() => {
        console.warn = originalWarn;
        Object.defineProperty(Mendel, 'Daemon', daemonDescriptor);
        Object.defineProperty(Mendel, 'Client', clientDescriptor);
    });

    const done = new Promise((resolve) => {
        const mendel = new Mendel({});
        mendel.run(resolve);
    });
    const error = await done;

    t.equal(error, null, 'the recycled build still completes');
    t.match(
        warnings.join('\n'),
        /Instance of builder may be running/,
        'the warning names the likely running builder'
    );
    t.match(
        warnings.join('\n'),
        /Attemping to recycle/,
        'the warning says the builder is being recycled'
    );
});

const tap = require('tap');
const path = require('path');
const fs = require('fs');
const os = require('os');
const { spawn } = require('child_process');
const { stageFixture } = require('./helpers');

const appPath = stageFixture(
    path.resolve(__dirname, './fixtures/uncaught-outlet'),
    'cli-uncaught-exception'
);
const mendelrcPath = path.join(appPath, '.mendelrc');
// Unix socket paths are capped near 104 bytes; a path under the fixture would
// silently truncate on a deep checkout.
const ipcPath = path.join(os.tmpdir(), `mendel-cue-${process.pid}.sock`);
const cliPath = path.resolve(__dirname, '../src/cli.js');

const YAML = `base-config:
  id: base
  dir: ./app
  outdir: ./build

variation-config:
  variation-dirs: []
  variations: {}

transforms: {}

types:
  js:
    extensions:
      - .js

outlets:
  - id: js-bundle
    plugin: ${path.join(appPath, 'outlet-boom.js')}

bundles:
  main:
    outlet: js-bundle
    entries:
      - ./main.js
`;

function runCli() {
    return new Promise((resolve) => {
        const proc = spawn(process.execPath, [cliPath], {
            cwd: appPath,
            env: Object.assign({}, process.env, {
                MENDEL_IPC: ipcPath,
                MENDEL_ENV: 'development',
                NODE_ENV: 'development',
            }),
            stdio: ['ignore', 'pipe', 'pipe'],
        });
        let stderr = '';
        proc.stderr.on('data', (chunk) => (stderr += chunk));
        proc.on('close', (code) => resolve({ code, stderr }));
    });
}

tap.test(
    'an uncaught error in the builder force-closes with the stack',
    async (t) => {
        fs.writeFileSync(mendelrcPath, YAML);
        try {
            fs.unlinkSync(ipcPath);
        } catch (e) {
            /* no socket yet */
        }

        t.teardown(() => {
            [mendelrcPath, ipcPath].forEach((file) => {
                try {
                    fs.unlinkSync(file);
                } catch (e) {
                    /* already gone */
                }
            });
        });

        const { code, stderr } = await runCli();

        t.equal(
            code,
            1,
            'the builder force-closes with a nonzero exit code'
        );
        t.match(
            stderr,
            /Force closing due to a critical error:/,
            'the force-close banner is printed'
        );
        t.match(
            stderr,
            /Error: outlet boom/,
            'the uncaught stack is printed'
        );
    }
);

